contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmt, uint minSum, uint colAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmt);
        require(colAmt > 0);
        require(minSum <= depAmt);
        require(colAmt <= depAmt);
        require(colAmt >= minSum);

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(c)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: depAmt}(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(colAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && c.balances(address(this)) == balBefore + depAmt - colAmt && address(c).balance == cBalBefore + depAmt - colAmt);
    }

    receive() external payable {}
}

