    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depAmt, uint256 minSum, uint256 colAmt) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmt);
        vm.assume(colAmt > 0);
        vm.assume(minSum <= depAmt);
        vm.assume(colAmt <= depAmt);
        vm.assume(colAmt >= minSum);
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 cBalBefore = address(c).balance;
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(c)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depAmt}() {} catch { return; }
        bool reverted;
        try c.Collect(colAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && c.balances(address(this)) == balBefore + depAmt - colAmt && address(c).balance == cBalBefore + depAmt - colAmt);
    }

    function testFuzz_run(uint256 depAmt, uint256 minSum, uint256 colAmt) public {
